from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
attachment = Motor(Port.D, Direction.CLOCKWISE)
rightmotor = Motor(Port.F, Direction.CLOCKWISE)
leftmotor = Motor(Port.B, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(leftmotor, rightmotor, 63, 100)


# The main program starts here.
drive_base.use_gyro(True)
drive_base.straight(-55)
drive_base.arc(-900, angle=45, then=Stop.NONE)
drive_base.arc(-300, angle=60, then=Stop.NONE)
drive_base.turn(-35)
drive_base.settings(straight_speed=115)
drive_base.straight(-270)
drive_base.settings(straight_speed=300)
drive_base.straight(120)
drive_base.turn(-75)
drive_base.straight(165)
drive_base.straight(-280)
drive_base.turn(45)
attachment.run_angle(500, 100)
drive_base.straight(400)
drive_base.turn(63)
drive_base.straight(30)
attachment.run_angle(150, 80)
wait(1750)
attachment.run_angle(150, -120)
drive_base.settings(straight_speed=155)
drive_base.turn(13)
wait(10)
attachment.run_angle(150, -40)
drive_base.straight(-21)
drive_base.turn(-30)
drive_base.straight(190)
drive_base.turn(30)
drive_base.arc(-1060, angle=51)
